import {el,action,safeUrl} from '../core/dom.js';
export const links={type:'links',version:1,title:'Под рукой',description:'Нужные сайты и материалы без поиска по вкладкам.',icon:'links',tone:'sand',size:{w:280,h:230},createData:()=>({items:[]}),validate:d=>Array.isArray(d.items)&&d.items.length<=200&&d.items.every(item=>typeof item.title==='string'&&typeof item.url==='string'&&safeUrl(item.url)),
renderCard({node,open}){return el('div',{class:'links-preview'},node.data.items.length?node.data.items.slice(0,3).map(item=>el('a',{href:safeUrl(item.url),rel:'noreferrer',class:'bookmark'},el('span',{},item.title),el('span',{'aria-hidden':'true'},'→'))):el('p',{class:'muted'},'Сохрани ссылки, которые нужны для дела.'),action('Все ссылки ↗',open,'text-button'));},
renderScreen(ctx){const root=el('div');function render(){root.replaceChildren();const title=el('input',{placeholder:'Название',required:true,maxlength:160,'aria-label':'Название ссылки'}),url=el('input',{type:'url',placeholder:'https://…',required:true,'aria-label':'Адрес ссылки'});const error=el('p',{class:'form-error',role:'alert'});root.append(el('form',{class:'link-form',onSubmit:e=>{e.preventDefault();const href=safeUrl(url.value);if(!href){error.textContent='Нужен адрес с https:// или http://';return;}ctx.update({items:[...ctx.latest().data.items,{title:title.value.trim()||href,url:href}]});render();}},title,url,el('button',{class:'button primary',type:'submit'},'Добавить'),error));ctx.latest().data.items.forEach((item,index)=>root.append(el('div',{class:'link-edit'},el('a',{href:safeUrl(item.url),rel:'noreferrer'},el('strong',{},item.title),el('small',{},item.url)),action('Удалить',()=>{ctx.update({items:ctx.latest().data.items.filter((_,i)=>i!==index)});render();},'text-button'))));}render();return root;}
};
